function whenAllOutcome(tasks) {
  for (const task of tasks) {
    if (task.state === 'faulted') {
      return 'faulted:' + task.id;
    }
  }
  for (const task of tasks) {
    if (task.state === 'canceled') {
      return 'canceled';
    }
  }
  return 'completed';
}

