    }
  }
  return 'completed';
}

items.workedExampleMarkdown:
A chain that works, and the one-line change that breaks it.

```csharp
// Handler: the framework supplies a token tied to the client connection.
public async Task<IActionResult> Get(string id, CancellationToken ct)
{
    var view = await _service.LoadAsync(id, ct);
    return Ok(view);
}

// Service: forwards the token to everything it calls.
public async Task<TicketView> LoadAsync(string id, CancellationToken ct)
{
    var ticket = await _repo.GetAsync(id, ct);

    foreach (var attachment in ticket.Attachments)
    {
        ct.ThrowIfCancellationRequested();     // our own loop participates
        await _scanner.ScanAsync(attachment, ct);
    }

    return new TicketView(ticket);
}

// Repository: the break.
public Task<Ticket> GetAsync(string id, CancellationToken ct)
{
    return _db.Tickets.FirstAsync(t => t.Id == id);   // token NOT passed
}
```

The repository compiles, its tests pass, and it accepts a token it then ignores. Everything below it is uncancellable, so a client that disconnects leaves the query running to completion. The fix is one argument — `FirstAsync(t => t.Id == id, ct)` — and the reason it is worth hunting for is that nothing else will ever tell you.

Handling it as an expected outcome:

```csharp
try
{
    return Ok(await _service.LoadAsync(id, ct));
}
catch (OperationCanceledException) when (ct.IsCancellationRequested)
{
    return StatusCode(499);   // client closed the request; not a server error
}
```

